1	#!/usr/bin/env node
2	// Emits the Lore test-command `list` shape: a single JSON array of
3	// {id, name, file} objects, one per test, and nothing else on stdout.
4	// Jest cannot resolve test names without executing them - there is no
5	// dry-run - so the suite is run once with --json written to a temp file and
6	// progress sent to stderr, keeping stdout pure.
7	// The id is "<repo-relative-file>::<full test name>" - stable across runs,
8	// and exactly what the run command's {selector} splits back apart.
9	import {execFileSync} from 'node:child_process';
10	import {readFileSync, rmSync} from 'node:fs';
11	import {tmpdir} from 'node:os';
12	import {join, relative} from 'node:path';
13	import process from 'node:process';
14	
15	const reportFile = join(tmpdir(), `hal-engine-jest-report-${process.pid}.json`);
16	
17	try {
18	  execFileSync('npx', ['jest', '--json', `--outputFile=${reportFile}`], {
19	    cwd: process.cwd(),
20	    stdio: ['ignore', 'ignore', 'inherit'],
21	    // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
22	    env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
23	  });
24	} catch {
25	  // A failing test still produces a full report, and listing must not depend
